CREATE TABLE "Rooms" (
    "Id"            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "HotelId"       INTEGER NOT NULL REFERENCES "Hotels" ("Id") ON DELETE CASCADE,
    "RoomNumber"    TEXT NOT NULL,
    "RoomType"      TEXT NOT NULL,
    "Capacity"      INTEGER NOT NULL CHECK ("Capacity" > 0),
    "PricePerNight" NUMERIC(10, 2) NOT NULL CHECK ("PricePerNight" >= 0),
    "IsActive"      BOOLEAN NOT NULL DEFAULT TRUE,
    "CreatedAtUtc"  TIMESTAMPTZ NOT NULL,
    "UpdatedAtUtc"  TIMESTAMPTZ NOT NULL,
    CONSTRAINT "UQ_Rooms_Id_HotelId" UNIQUE ("Id", "HotelId")
);

CREATE UNIQUE INDEX "IX_Rooms_HotelId_RoomNumber" ON "Rooms" ("HotelId", "RoomNumber");

-- Each hotel gets a mix of room types; one room per hotel is disabled.
INSERT INTO "Rooms" ("HotelId", "RoomNumber", "RoomType", "Capacity", "PricePerNight", "IsActive", "CreatedAtUtc", "UpdatedAtUtc")
SELECT h."Id", r.num, r.type, r.cap, ROUND(r.price * h.factor, 2), r.active, now(), now()
FROM (
    SELECT "Id", CASE "Id" WHEN 1 THEN 1.2 WHEN 2 THEN 1.0 WHEN 3 THEN 0.8 WHEN 4 THEN 1.6 ELSE 1.8 END AS factor
    FROM "Hotels"
) h
CROSS JOIN (VALUES
    ('101', 'Single', 1,  60.00, TRUE),
    ('102', 'Single', 1,  60.00, TRUE),
    ('201', 'Double', 2,  95.00, TRUE),
    ('202', 'Double', 2,  95.00, TRUE),
    ('203', 'Double', 3, 110.00, TRUE),
    ('301', 'Suite',  4, 220.00, TRUE),
    ('302', 'Suite',  5, 260.00, FALSE)
) AS r (num, type, cap, price, active);
